package io.undertow.server.protocol.http;

import io.undertow.connector.ByteBufferPool;
import io.undertow.connector.PooledByteBuffer;
import io.undertow.server.ConnectorStatisticsImpl;
import io.undertow.server.protocol.http.HttpServerConnection;
import io.undertow.server.protocol.http.RequestParser;
import io.undertow.UndertowOptions;
import org.xnio.OptionMap;
import io.undertow.conduits.ReadDataStreamSourceConduit;
import org.xnio.conduits.ConduitStreamSourceChannel;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.xnio.conduits.StreamSinkConduit;

import java.io.IOException;
import java.nio.ByteBuffer;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class HttpReadListenerHandleEventWithNoRunningRequestTests {

    @Test
    void handleEventWithNoRunningRequest_IOExceptionClosesAndFreesBuffer() throws Exception {
        // Mocks for production classes
        HttpServerConnection connection = Mockito.mock(HttpServerConnection.class, Mockito.RETURNS_DEEP_STUBS);
        RequestParser parser = Mockito.mock(RequestParser.class);
        ConnectorStatisticsImpl connectorStatistics = Mockito.mock(ConnectorStatisticsImpl.class);

        // Undertow options to allow HttpReadListener constructor to initialize without NPEs
        OptionMap undertowOpts = Mockito.mock(OptionMap.class);
        when(connection.getUndertowOptions()).thenReturn(undertowOpts);
        when(undertowOpts.contains(Mockito.any())).thenReturn(false);
        when(undertowOpts.get(UndertowOptions.MAX_HEADER_SIZE, UndertowOptions.DEFAULT_MAX_HEADER_SIZE)).thenReturn(8192);
        when(undertowOpts.get(UndertowOptions.MAX_ENTITY_SIZE, UndertowOptions.DEFAULT_MAX_ENTITY_SIZE)).thenReturn(1048576L);
        when(undertowOpts.get(UndertowOptions.RECORD_REQUEST_START_TIME, false)).thenReturn(false);
        when(undertowOpts.get(UndertowOptions.ALLOW_UNKNOWN_PROTOCOLS, UndertowOptions.DEFAULT_ALLOW_UNKNOWN_PROTOCOLS)).thenReturn(true);
        when(undertowOpts.get(UndertowOptions.REQUEST_PARSE_TIMEOUT, -1)).thenReturn(-1);
        when(undertowOpts.get(UndertowOptions.NO_REQUEST_TIMEOUT, -1)).thenReturn(-1);

        // ByteBufferPool and a pooled buffer to be returned by allocate()
        ByteBufferPool byteBufferPool = Mockito.mock(ByteBufferPool.class);
        when(connection.getByteBufferPool()).thenReturn(byteBufferPool);

        PooledByteBuffer pooledBuffer = Mockito.mock(PooledByteBuffer.class);
        ByteBuffer buffer = ByteBuffer.allocate(256);
        when(pooledBuffer.getBuffer()).thenReturn(buffer);
        when(byteBufferPool.allocate()).thenReturn(pooledBuffer);

        // Simulate existing extra bytes as null (no running extra bytes)
        when(connection.getExtraBytes()).thenReturn(null);

        // Source conduit read and sink conduit behavior
        ReadDataStreamSourceConduit sourceConduit = Mockito.mock(ReadDataStreamSourceConduit.class);
        when(connection.getOriginalSourceConduit()).thenReturn(sourceConduit);
        when(sourceConduit.isReadShutdown()).thenReturn(false);

        // Original sink conduit must exist and indicate not shutdown for this path
        StreamSinkConduit sinkConduit = Mockito.mock(StreamSinkConduit.class);
        when(connection.getOriginalSinkConduit()).thenReturn(sinkConduit);
        when(sinkConduit.isWriteShutdown()).thenReturn(false);

        // Channel that will throw IOException on read
        ConduitStreamSourceChannel channel = Mockito.mock(ConduitStreamSourceChannel.class);
        // Channel.read(buffer) should throw IOException for this test path
        Mockito.doThrow(new IOException("boom")).when(channel).read(any(ByteBuffer.class));

        HttpReadListener listener = new HttpReadListener(connection, parser, connectorStatistics);

        // Act
        listener.handleEventWithNoRunningRequest(channel);

        // Assert expectations: buffer allocation occurred, and the allocated buffer was released in finally
        verify(byteBufferPool).allocate();
        verify(pooledBuffer).close();
        verify(channel).read(any(ByteBuffer.class));
    }
}

