package io.undertow.util;

import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

public class PathTemplateCreateTests {

    @Test
    void testNullInputThrows() {
        assertThrows(IllegalArgumentException.class, () -> PathTemplate.create(null));
    }

    @Test
    void testPrependSlashIfMissingAndEquality() {
        PathTemplate a = PathTemplate.create("foo");
        PathTemplate b = PathTemplate.create("/foo");
        assertEquals(a, b, "Templates should be equal after normalizing missing leading slash");
    }

    @Test
    void testTemplateExtractionAndParameters() {
        PathTemplate t = PathTemplate.create("/users/{id}");
        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/users/123", params), "Template should match a concrete path");
        assertEquals("123", params.get("id"), "Template should capture id parameter");
        assertEquals(Set.of("id"), t.getParameterNames(), "Parameter names should include 'id'");
    }

    @Test
    void testTrailingSlashBehavior() {
        PathTemplate t = PathTemplate.create("/users/{id}/");
        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/users/123/", params), "Template with trailing slash should match when path ends with /");
        assertEquals("123", params.get("id"));

        Map<String, String> params2 = new HashMap<>();
        assertFalse(t.matches("/users/123", params2), "Trailing slash should cause non-match when missing trailing slash");
    }

    @Test
    void testWildcardStar() {
        PathTemplate t = PathTemplate.create("/foo/*");
        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo/abc/def", params), "Wildcard path should match remainder after base");
        assertEquals("abc/def", params.get("*"));
    }

    @Test
    void testLiteralOnlyPath() {
        PathTemplate t = PathTemplate.create("/admin");
        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/admin", params), "Literal path should match exact path");
        assertTrue(params.isEmpty(), "No parameters should be captured for literal path");
    }
}

