    void testNullInputThrows() {
        assertThrows(IllegalArgumentException.class, () -> PathTemplate.create(null));
    }

    @Test
    void testPrependSlashWhenMissingAndBase() {
        PathTemplate t = PathTemplate.create("foo");
        // When input lacked a leading '/', the path should be prefixed with '/'
        assertEquals("/foo", t.getTemplateString());
        assertEquals("/foo", t.getBase());

        // Matching the exact path should succeed
        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo", params));
        // No parameters expected for a simple path
        assertTrue(t.getParameterNames().isEmpty());
    }

    @Test
    void testTrailingSlashBehavior() {
        PathTemplate t = PathTemplate.create("/foo/");
        // trailingSlash should be honored by the template logic
        assertEquals("/foo/", t.getBase());

        // Should match when path ends with a trailing slash
        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo/", params));

        // Should not match when trailing slash is missing
        assertFalse(t.matches("/foo", new HashMap<>()));
    }

    @Test
    void testTemplateParameterExtraction() {
        PathTemplate t = PathTemplate.create("/Hello/{name}/world");
        assertTrue(t.getParameterNames().contains("name"));

        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/Hello/John/world", params));
        assertEquals("John", params.get("name"));
    }

    @Test
    void testInputWithoutLeadingSlashResolved() {
        PathTemplate t1 = PathTemplate.create("/bar/{baz}");
        PathTemplate t2 = PathTemplate.create("bar/{baz}");

        // The two templates should be equivalent after normalization
        assertEquals(t1.getTemplateString(), t2.getTemplateString());
        assertEquals(t1.getBase(), t2.getBase());

        Map<String, String> m = new HashMap<>();
        assertTrue(t2.matches("/bar/VAL", m));
        assertEquals("VAL", m.get("baz"));
    }

    @Test
    void testInvalidTemplateThrows() {
        // Missing closing brace should throw an exception
        assertThrows(RuntimeException.class, () -> PathTemplate.create("/bad{name"));
    }
}

