package io.undertow.util;

import io.undertow.util.PathTemplate;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class PathTemplateCreateTests {

    @Test
    void testCreateNullThrowsPathMustBeSpecified() {
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class, () -> PathTemplate.create(null));
        assertTrue(ex.getMessage().contains("Path must be specified"));
    }

    @Test
    void testLeadingSlashPrefixNormalization() {
        PathTemplate pWithLeading = PathTemplate.create("/foo/{id}");
        PathTemplate pWithoutLeading = PathTemplate.create("foo/{id}");
        assertEquals(pWithLeading, pWithoutLeading, "Paths without leading slash should normalize to the same template as with leading slash");
    }

    @Test
    void testTemplateParameterExtraction() {
        PathTemplate p = PathTemplate.create("/foo/{id}/bar");
        assertEquals("/foo/{id}/bar", p.getTemplateString());
        assertEquals("/foo/", p.getBase());
        assertTrue(p.getParameterNames().contains("id"), "Parameter name 'id' should be extracted from template");
        assertTrue(p.getParameterNames().size() == 1, "Only 'id' should be captured as a parameter");
    }

    @Test
    void testTrailingSlashAndNoTemplates() {
        PathTemplate p = PathTemplate.create("/foo/");
        // base should reflect the entire path when there is a trailing slash with no templates
        assertEquals("/foo/", p.getBase());
        assertTrue(p.getParameterNames().isEmpty(), "No template parameters should be extracted when none are present");
        assertEquals("/foo/", p.getTemplateString());
    }

    @Test
    void testAsteriskInBaseNoTemplateNames() {
        PathTemplate p = PathTemplate.create("/a*/bar");
        // base should reflect the asterisk-containing segment, and there should be no template parameters
        assertEquals("/a*", p.getBase());
        assertTrue(p.getParameterNames().isEmpty(), "No parameters should be extracted when base contains '*'");
    }

