    void testMissingClosingBraceThrows() {
        RuntimeException ex = assertThrows(RuntimeException.class, () -> PathTemplate.create("/a{b"));
        assertTrue(ex.getMessage().contains("Could not parse URI template"));
    }
}

package io.undertow.util;

