    public void testNullInputThrows() {
        assertThrows(IllegalArgumentException.class, () -> PathTemplate.create(null));
    }

    @Test
    public void testLeadingSlashNormalization() {
        PathTemplate withoutSlash = PathTemplate.create("abc");
        PathTemplate withSlash = PathTemplate.create("/abc");

        assertEquals(withSlash.getTemplateString(), "/abc");
        assertEquals(withSlash.getBase(), "/abc");

        assertEquals(withoutSlash.getTemplateString(), withSlash.getTemplateString());
        assertEquals(withoutSlash.getBase(), withSlash.getBase());
    }

    @Test
    public void testSimpleLiteralPathParsesBaseAndMatches() {
        PathTemplate t = PathTemplate.create("/foo/bar");

        assertEquals("/foo/bar", t.getTemplateString());
        assertEquals("/foo/bar", t.getBase());
        assertTrue(t.getParameterNames().isEmpty());

        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo/bar", params));
        assertTrue(params.isEmpty());
    }

    @Test
    public void testTemplateNameAndMatching() {
        PathTemplate t = PathTemplate.create("/foo/{name}/bar");

        assertEquals("/foo/{name}/bar", t.getTemplateString());
        assertEquals("/foo", t.getBase());
        Set<String> paramNames = t.getParameterNames();
        assertTrue(paramNames.contains("name"));
        assertEquals(1, paramNames.size());

        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo/Alice/bar", params));
        assertEquals("Alice", params.get("name"));
    }

    @Test
    public void testTrailingSlashParsing() {
        PathTemplate t = PathTemplate.create("/foo/{name}/");

        assertEquals("/foo/{name}/", t.getTemplateString());
        assertEquals("/foo", t.getBase());
        assertTrue(t.getParameterNames().contains("name"));

        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo/Bob/", params));
        assertEquals("Bob", params.get("name"));

        Map<String, String> noSlash = new HashMap<>();
        // Without trailing slash, should not match when trailingSlash is required
        assertFalse(t.matches("/foo/Bob", noSlash));
        // Ensure the map is cleared on non-match
        assertTrue(noSlash.isEmpty() || noSlash.get("name") == null);
    }

    @Test
    public void testWildcardBaseMatches() {
        PathTemplate t = PathTemplate.create("/foo/*");

        assertEquals("/foo/*", t.getTemplateString());
        assertEquals("/foo/*", t.getBase());
        assertTrue(t.getParameterNames().isEmpty());

        Map<String, String> params = new HashMap<>();
        assertTrue(t.matches("/foo/anything/else", params));
        assertEquals("anything/else", params.get("*"));
    }

    @Test
    public void testParseErrorUnclosedTemplateThrows() {
        assertThrows(RuntimeException.class, () -> PathTemplate.create("/foo/{name"));
    }

}

