package io.undertow.util;

import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class PathTemplateCreateTests {

    @Test
    public void testNullInputThrows() {
        assertThrows(RuntimeException.class, () -> PathTemplate.create(null));
    }

    @Test
    public void testLeadingSlashPrependedForNoLeadingSlash() {
        PathTemplate pt = PathTemplate.create("bar");
        assertNotNull(pt);
        assertEquals("/bar", pt.getTemplateString());
        assertEquals("/bar", pt.getBase()); // base should be same since there are no templates
        assertTrue(pt.getParameterNames().isEmpty());
    }

    @Test
    public void testPlainPathMatchesExactPath() {
        PathTemplate pt = PathTemplate.create("/static/path");
        Map<String, String> params = new HashMap<>();
        assertTrue(pt.matches("/static/path", params));
        assertTrue(params.isEmpty());
    }

    @Test
    public void testTemplateWithParameterParsesAndMatches() {
        PathTemplate pt = PathTemplate.create("/foo/{bar}");
        assertNotNull(pt);
        assertEquals("/foo/{bar}", pt.getTemplateString());
        assertEquals("/foo", pt.getBase());
        assertTrue(pt.getParameterNames().contains("bar"));

        Map<String, String> params = new HashMap<>();
        assertTrue(pt.matches("/foo/123", params));
        assertEquals("123", params.get("bar"));
    }

    @Test
    public void testTemplateWithTrailingSlashMatchesWithSlash() {
        PathTemplate pt = PathTemplate.create("/foo/{bar}/");
        assertNotNull(pt);
        // Base should stop before the template
        assertEquals("/foo/", pt.getBase());
        assertTrue(pt.getParameterNames().contains("bar"));

        Map<String, String> params = new HashMap<>();
        // Should match with trailing slash
        assertTrue(pt.matches("/foo/123/", params));
        assertEquals("123", params.get("bar"));

        // Should not match without trailing slash
        Map<String, String> params2 = new HashMap<>();
        assertFalse(pt.matches("/foo/123", params2));
        assertTrue(params2.isEmpty());
    }

    @Test
    public void testUnclosedTemplateThrows() {
        assertThrows(RuntimeException.class, () -> PathTemplate.create("/foo/{bar"));
    }

    @Test
    public void testMalformedTemplateMissingSeparatorThrows() {
        // After a template segment, there must be a '/' to separate or end-of-string
        // Here, after template we have an extra non-slash character
        assertThrows(RuntimeException.class, () -> PathTemplate.create("/foo/{bar}x"));
    }

    @Test
    public void testBaseIncludesNoWildcardWhenNoStar() {
        PathTemplate pt = PathTemplate.create("/simple/{id}");
        assertNotNull(pt);
        // Ensure template flag is set (via parameter names) and base is captured without a trailing wildcard
        assertTrue(pt.getParameterNames().contains("id"));
        assertEquals("/simple", pt.getBase());
    }

    @Test
    public void testSimpleWildcardPath() {
        // Ensure simple path with star behaves in a predictable way (basic sanity)
        // This validates that creation doesn't crash for star-containing paths
        PathTemplate pt = PathTemplate.create("/a/*");
        assertNotNull(pt);
        // Basic sanity checks: template should be false for simple wildcard tail
        assertFalse(pt.getParameterNames().contains(""));

        // Matching behavior for wildcard tail
        Map<String, String> params = new HashMap<>();
        assertTrue(pt.matches("/a/b/c", params) || pt.matches("/a/", new HashMap<>()));
    }
}

