package io.undertow.util;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class URLUtilsDecodeTests {

    @Test
    public void testNoChangeWhenNoEncoding() {
        String s = "abc123";
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", true, true, buffer);
        assertEquals(s, res, "If no encoding characters are present, the input should be returned unchanged.");
        assertEquals(0, buffer.length(), "Buffer should remain empty when no decoding occurs.");
    }

    @Test
    public void testPlusSignsAreConvertedToSpacesWhenFormEncoding() {
        String s = "a+b+c";
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", true, true, buffer);
        assertEquals("a b c", res, "When formEncoding is true, '+' should be decoded to spaces.");
    }

    @Test
    public void testPlusSignsPreservedWhenFormEncodingDisabled() {
        String s = "a+b";
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", true, false, buffer);
        assertEquals("a+b", res, "When formEncoding is disabled, '+' should be preserved in the output.");
    }

    @Test
    public void testEncodedSlashDecodedWhenSlashDecodingEnabled() {
        String s = "%2F";
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", true, true, buffer);
        assertEquals("/", res, "With slash decoding enabled, '%2F' should decode to '/'");
    }

    @Test
    public void testEncodedSlashPreservedWhenSlashDecodingDisabled() {
        String s = "%2F";
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", false, true, buffer);
        assertEquals("%2F", res, "When slash decoding is disabled, '%2F' should be preserved in output.");
    }

    @Test
    public void testEncodedSlashPreservedCaseWhenDecodingDisabled() {
        String s = "%2F";
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", false, true, buffer);
        assertEquals("%2F", res, "Case of the encoded slash should be preserved when not decoding slashes.");
    }

    @Test
    public void testUnicodeMultiByteDecoding() {
        String s = "%C3%A9"; // é in UTF-8
        StringBuilder buffer = new StringBuilder();
        String res = URLUtils.decode(s, "UTF-8", true, true, buffer);
        assertEquals("é", res, "Multi-byte UTF-8 sequences should decode correctly to the corresponding character.");
    }

    @Test
    public void testMalformedPercentCodeThrowsIllegalArgumentException() {
        String s = "%G1";
        StringBuilder buffer = new StringBuilder();
        assertThrows(IllegalArgumentException.class, () -> URLUtils.decode(s, "UTF-8", true, true, buffer),
                "Malformed percent-encoded sequences should throw IllegalArgumentException.");
    }

}

