import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class URLUtilsDecodeTests {

    @Test
    void testDecodeSimplePercentEncoding() {
        String s = "abc%20def";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, true, true, buffer);
        assertEquals("abc def", result);
        assertEquals("abc def", buffer.toString());
    }

    @Test
    void testDecodePlusToSpaceFormEncoding() {
        String s = "A+B+C";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, true, true, buffer);
        assertEquals("A B C", result);
        assertEquals("A B C", buffer.toString());
    }

    @Test
    void testDecodeSlashPreservedWhenNotDecoded() {
        String s = "%2Fpath";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, false, true, buffer);
        // When decodeSlash is false, encoded slash should be preserved as "%2F"
        assertEquals("%2Fpath", result);
        assertEquals("%2Fpath", buffer.toString());
    }

    @Test
    void testDecodeSlashDecodedToSlash() {
        String s = "%2Fpath";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, true, true, buffer);
        assertEquals("/path", result);
        assertEquals("/path", buffer.toString());
    }

    @Test
    void testDecodeNonAsciiUtf8Sequence() {
        String s = "caf%C3%A9";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, true, true, buffer);
        assertEquals("café", result);
        assertEquals("café", buffer.toString());
    }

    @Test
    void testNoChangeWhenNoEncodingPresent() {
        String s = "abcdef123";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, true, true, buffer);
        // No encoding changes expected, so the original string should be returned
        assertEquals(s, result);
    }

    @Test
    void testInvalidPercentEncodingThrows() {
        String s = "abc%2";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        assertThrows(IllegalArgumentException.class, () -> URLUtils.decode(s, enc, true, true, buffer));
    }

    @Test
    void testDecodeUsingOverloadWithFormEncoding() {
        // Using the overload that defaults to formEncoding = true
        String s = "A+B+C";
        String enc = "UTF-8";
        StringBuilder buffer = new StringBuilder();
        String result = URLUtils.decode(s, enc, true, buffer);
        assertEquals("A B C", result);
        assertEquals("A B C", buffer.toString());
    }
}

