        String result = URLUtils.decode(s, "UTF-8", true, true, new StringBuilder());
        assertEquals("hello world test", result, "Plus signs should be converted to spaces when form encoding is enabled");
    }

    @Test
    void testMalformedPercentThrowsUrlDecodeException() {
        String s = "%2"; // incomplete percent-encoding
        assertThrows(UrlDecodeException.class, () -> URLUtils.decode(s, "UTF-8", true, true, new StringBuilder()),
                "Malformed percent-encoded sequences should throw UrlDecodeException");
    }

