        assertEquals("/", result, "Encoded slash should be decoded when decodeSlash is true");
    }

    @Test
    void testLowercaseHexDecoded() {
        String s = "%2f";
        String result = URLUtils.decode(s, "UTF-8", true, true, new StringBuilder());
        assertEquals("/", result, "Hex digits should be case-insensitive when decoding");
    }

