    void testChineseDecoded() {
        String s = "%E4%BD%A0%E5%A5%BD"; // "你好" in UTF-8
        String result = URLUtils.decode(s, "UTF-8", true, true, new StringBuilder());
        assertEquals("你好", result, "Unicode characters should be decoded correctly from UTF-8");
    }
}

