import java.util.HashMap;
import io.undertow.server.HttpHandler;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.ServerConnection;

public class RewriteHandlerHandleRequestTests {

    // Minimal local test harness to avoid external test dependencies
    @SuppressWarnings("all")
    public @interface Test {}

    static class Assertions {
        static void assertTrue(boolean condition, String message) {
            if (!condition) throw new AssertionError(message);
        }
        static void assertNull(Object obj, String message) {
            if (obj != null) throw new AssertionError(message);
        }
    }

    // Simple Recording HttpHandler to verify that next is invoked
    static class RecordingHandler implements HttpHandler {
        private boolean called = false;

        @Override
        public void handleRequest(HttpServerExchange exchange) throws Exception {
            this.called = true;
        }

        boolean wasCalled() {
            return called;
        }
    }

    @Test
    void testHandleRequest_noRules_callsNext() throws Exception {
        RecordingHandler next = new RecordingHandler();
        RewriteConfig config = new RewriteConfig(new RewriteRule[0], new HashMap<>());
        RewriteHandler handler = new RewriteHandler(config, next);

        HttpServerExchange exchange = new HttpServerExchange((ServerConnection) null);
        handler.handleRequest(exchange);

        Assertions.assertTrue(next.wasCalled(), "Next should be invoked when there are no rewrite rules");
    }

    @Test
    void testHandleRequest_invokedPath_callsNext_andResetsFlag() throws Exception {
        RecordingHandler next = new RecordingHandler();
        RewriteRule[] rules = new RewriteRule[] { new RewriteRule() };
        RewriteConfig config = new RewriteConfig(rules, new HashMap<>());
        RewriteHandler handler = new RewriteHandler(config, next);

        // Simulate that the rewrite handler has already been invoked in this thread
        handler.invoked.set(Boolean.TRUE);

        HttpServerExchange exchange = new HttpServerExchange((ServerConnection) null);
        handler.handleRequest(exchange);

        Assertions.assertTrue(next.wasCalled(), "Next should be invoked when invoked flag is set");
        Assertions.assertNull(handler.invoked.get(), "Invoked flag should be reset after handling");
    }
}

