import java.lang.reflect.Method;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class AnnotatedEndpointFactoryCreateTests {

    // A minimal endpoint with a single OnOpen, OnMessage and OnClose, to verify basic binding
    public static class SimpleEndpoint {
        @jakarta.websocket.OnOpen
        public void onOpen(jakarta.websocket.Session session, jakarta.websocket.EndpointConfig config) {
        }

        @jakarta.websocket.OnMessage
        public String onText(jakarta.websocket.Session session, String text) {
            return text;
        }

        @jakarta.websocket.OnClose
        public void onClose(jakarta.websocket.Session session, jakarta.websocket.CloseReason reason) {
        }
    }

    // An endpoint with two OnOpen methods to trigger a DeploymentException
    public static class TwoOpensEndpoint {
        @jakarta.websocket.OnOpen
        public void open1(jakarta.websocket.Session s, jakarta.websocket.EndpointConfig cfg) { }

        @jakarta.websocket.OnOpen
        public void open2(jakarta.websocket.Session s, jakarta.websocket.EndpointConfig cfg) { }
    }

    // An endpoint with an OnMessage that has an unsupported parameter type (no encoding found)
    public static class UnsupportedMessageEndpoint {
        @jakarta.websocket.OnOpen
        public void open(jakarta.websocket.Session s, jakarta.websocket.EndpointConfig cfg) { }

        @jakarta.websocket.OnMessage
        public void onMessage(jakarta.websocket.Session s, Object unsupported) { }
    }

    @Test
    public void testSimpleEndpointCreatesFactory() throws Exception {
        EncodingFactory encodingFactory = EncodingFactory.DEFAULT;
        Set<String> paths = new HashSet<>(Collections.singleton("p1"));

        AnnotatedEndpointFactory factory = AnnotatedEndpointFactory.create(SimpleEndpoint.class, encodingFactory, paths);
        assertNotNull(factory, "Factory should be created for a valid endpoint");
        // We can't access private fields directly, but we can exercise creation pathway
        // by ensuring createInstance would be possible without throwing (requires runtime InstanceHandle),
        // so we at least confirm that the factory instance is created for a valid class.
        assertEquals(SimpleEndpoint.class, factory.endpointClass, "Endpoint class should be preserved in factory");
    }

    @Test
    public void testMultipleOnOpenThrowsDeploymentException() {
        EncodingFactory encodingFactory = EncodingFactory.DEFAULT;
        Set<String> paths = new HashSet<>();
        try {
            AnnotatedEndpointFactory.create(TwoOpensEndpoint.class, encodingFactory, paths);
            fail("Expected DeploymentException due to multiple OnOpen methods");
